/**
 * The six values of a recognition configuration, as the settings hold
 * them (R18): the chosen configuration in the shared settings, or the
 * configuration in use on this computer.
 */
export type RecognitionChoice = { 
/**
 * Catalog id of the transcription model (KTD6).
 */
asr_model: string; 
/**
 * A streaming model transcribes during recording (R18, KD9).
 */
live_transcript: boolean; speaker_source: SpeakerSource; speaker_processing_mode: ProcessingMode; recognition_language: string | null; default_speaker_count: SpeakerCountSetting | null }
export type RecognitionConfig = { asr_model: string; speaker_source: SpeakerSource; processing_mode: ProcessingMode; speaker_processing_mode?: ProcessingMode; speaker_count: SpeakerCount | null; language: string | null }
/**
 * A failed download of a file that the chosen configuration needs (R19).
 */
export type RecognitionFailure = { 
/**
 * The catalog id of the file.
 */
model_id: string; 
/**
 * The cause, as Settings shows it.
 */
message: string }
/**
 * The chosen recognition configuration compared with the configuration in
 * use, for the Settings window (R18, R19).
 */
export type RecognitionState = { 
/**
 * The chosen configuration differs from the configuration in use. A
 * chosen configuration with a value that this version does not know
 * always differs, so Settings tells the user to update.
 */
differs: boolean; 
/**
 * The chosen configuration has a value that this version does not
 * know, for example a model from a newer version. The configuration in
 * use stays, and no download starts.
 */
chosen_not_known: boolean; 
/**
 * The catalog ids of the files that the chosen configuration waits
 * for. `ModelDownloadEvent` gives the progress of each.
 */
waiting_for: string[]; 
/**
 * A download of the chosen configuration failed. It stays failed
 * until the user selects Retry.
 */
failure: RecognitionFailure | null }
/**
 * The recording button of the note page (R11, R12).
 */
export type RecordButton = { kind: RecordKind; 
/**
 * Record or Resume can start now.
 */
available: boolean; 
/**
 * Why the button is unavailable. `None` while it is available.
 */
reason: string | null }
/**
 * What the one recording button of the note page does (R11).
 */
export type RecordKind = 
/**
 * "Record": the note has no audio. The button calls `record_note`.
 */
"record" | 
/**
 * "Resume": the note has audio. The button calls `resume_recording`.
 */
"resume"
/**
 * A session started, stopped, or resumed recording.
 */
export type RecordingChanged = { 
/**
 * The session now recording; `None` once nothing is.
 */
session_id: string | null; 
/**
 * A segment opened for the session: a start, or a resume after a
 * stop, a pause or an interruption. The main window then shows the
 * note. A pause, a device switch or a restart gives `false`.
 */
opened: boolean }
export type RecordingStatus = { 
/**
 * The open session: recording, or interrupted and resumable.
 */
session_id: string | null; state: string | null; 
/**
 * A note is open: a segment records, a restart reopens the
 * microphone, or the note is paused.
 */
recording: boolean; 
/**
 * The user paused the open note (KTD1): no segment records, and the
 * stored state stays Capturing.
 */
paused: boolean; 
/**
 * The audio that the kept segments of the open note hold, gaps
 * excluded. While paused, it is the elapsed time that the page shows.
 */
recorded_ms: number; 
/**
 * The microphone went away and is being reopened (U14); the session
 * still counts as recording.
 */
reconnecting: boolean; 
/**
 * Why the open session stopped recording, while it is interrupted: the
 * failed-capture state, with Resume and Stop (R5c).
 */
interruption: Interruption | null; 
/**
 * Free bytes where audio is being written.
 */
working_free_bytes: number | null; 
/**
 * What a four-hour session at the microphone's rate needs there, its
 * processing included (R7b); `None` until the microphone is prepared.
 */
session_demand_bytes: number | null; 
/**
 * What each recorded second will need once processing begins.
 */
processing_bytes_per_second: number; 
/**
 * The free-space floor recording stops at (R7a).
 */
reserve_bytes: number; 
/**
 * The name of the input that the segment records from, while a
 * segment records (R2, R4).
 */
microphone: string | null; 
/**
 * The note's chosen microphone is missing, and the system default
 * records in its place (R4, R5).
 */
microphone_fallback: boolean; 
/**
 * The microphone that the open note chose. With no note open, the
 * microphone that the next note uses. `None` is "System default".
 */
microphone_choice: MicrophoneChoice | null; 
/**
 * The system audio permission is unknown, the output plays, and the
 * system audio channel has been digital silence for 10 s: system
 * audio can be missing (U5 step 6). It clears when audio appears.
 */
system_audio_silent: boolean; 
/**
 * The Computer audio switch of the open note (R8). With no note open,
 * the switch that the next note starts with (R6).
 */
system_audio: boolean; 
/**
 * A speaker stream is attached to the recording segment: the note
 * records system audio on the right now.
 */
system_audio_recording: boolean; 
/**
 * System audio is on, but the speaker stream failed or did not open.
 * The microphone records, the right channel holds silence, and the
 * capture watcher tries the speaker stream again (R10).
 */
system_audio_failed: boolean; 
/**
 * The last system audio permission check while system audio is on
 * and a segment records (KTD12). The page uses it to say why system
 * audio is not recorded: denied, not asked (the prompt can wait for an
 * answer), or unknown. `None` while system audio is off.
 */
system_audio_permission: SystemAudioPermission | null; 
/**
 * The output that Longhand follows has been silent for 30 s while
 * another output plays sound (Windows only, U4 step 6): the call can
 * play on a device that the note does not record.
 */
system_audio_other_output: boolean; 
/**
 * The system audio of the last 30 s held a late copy of the
 * microphone: an audio mixer app plays the microphone to an output, so
 * the note hears the user twice.
 */
system_audio_mic_copy: boolean }
/**
 * Work on a note on another computer (KTD5). Record, Resume, Transcribe
 * Again, Regenerate Summary, Remove Audio and Delete wait for it (R21),
 * except as R23 allows.
 */
export type RemoteView = 
/**
 * Another computer records into or processes the note (R12, R20).
 */
"in_use" | 
/**
 * Another computer recorded into the note and stopped before it saved
 * the recording: "Not finished on another computer" (R23). Notes
 * edits, and Delete after a confirmation, are available.
 */
"not_finished"
/**
 * Why Remove Audio did not complete (R13).
 */
export type RemoveAudioFailure = 
/**
 * The removal did not start. Nothing changed.
 */
{ kind: "refused"; message: string } | 
/**
 * The removal started and did not complete for each segment. A
 * segment that has its marker counts as removed, and the next pass
 * deletes its file (KTD2).
 */
{ kind: "failed"; message: string }
/**
 * The prompt that `restore_summary_prompt` added, and the settings after it.
 */
export type RestoredPrompt = { id: string; settings: Settings }
export type RuntimeSpec = { name: string; revision: string }
export type SessionDetail = { entry: SessionEntry; 
/**
 * Stages whose work is complete.
 */
done: string[]; 
/**
 * The stage started last.
 */
current: string | null; windows_done: number | null; windows_total: number | null; 
/**
 * The speaker stage's last saved progress while that stage runs.
 */
speakers: SpeakerProgressView | null; 
/**
 * The stage a failed session stopped at.
 */
failed_stage: string | null; 
/**
 * Why it failed, is blocked, or is waiting for its destination.
 */
message: string | null; 
/**
 * Why the summary is missing, when the session will be saved with a stub.
 */
summary_problem: string | null; 
/**
 * The state machine allows Resume now (R6a).
 */
resumable: boolean; 
/**
 * The recording button of the note page: Record or Resume, whether it
 * is available, and why not (R11, R12). `None` while the note records
 * or is interrupted. The work of another computer is in
 * `entry.remote`.
 */
record: RecordButton | null; home_path: string | null; 
/**
 * Where the summary goes, and what is sent: the transcript and notes (R30).
 */
endpoint: EndpointView | null; audio_kept: boolean; transcript_kept: boolean; 
/**
 * The audio of the note (KTD9). Transcribe Again, Resume and Retry
 * read it for their reason.
 */
audio: AudioView; 
/**
 * The recognition model that the note recorded when it started
 * (KTD2). `None` for a note that started before the update.
 */
asr_model: string | null; 
/**
 * The note records a live transcript (R8, R18). The Transcript tab
 * reads this, not the model selected now (R9).
 */
live_transcript: boolean; 
/**
 * A Transcribe Again run waits or runs (KTD14). It has no live text.
 */
transcribe_again: boolean; 
/**
 * A summary regeneration waits or runs. It continues when the user
 * leaves the note, so the page reads it here when the user comes back.
 */
regenerating: boolean; 
/**
 * The same stage failed again after a Retry. The next Retry starts
 * over from the recorded audio, after the user confirms.
 */
retry_starts_over: boolean; 
/**
 * Why the last Transcribe Again run failed. The note kept its
 * previous transcript and summary (R19).
 */
transcribe_again_error: string | null; 
/**
 * Why the last Transcribe Again run kept the previous summary with
 * the new transcript (R19).
 */
summary_not_updated: string | null; 
/**
 * The parts that the sync has not delivered yet (R6). Notes edits,
 * Regenerate Summary, Transcribe Again and Resume wait for them.
 */
waiting: WaitingPart[]; 
/**
 * The file or folder names of other versions of the note, which the
 * user resolves in Finder (R15).
 */
conflict_files: string[]; 
/**
 * Why the first write of the note's home folder waits, while it
 * tries again: the storage folder is not available, for example
 * (KTD4). The page shows "Not saved yet". `None` when the write is
 * done or has no problem.
 */
not_saved_yet: string | null }
export type SessionDocument = { has_speakers: boolean; lines: DocLine[]; 
/**
 * The text of `transcript.md`, which the Transcript tab copies (R17).
 */
transcript_markdown: string; summary: SummaryView | null }
export type SessionEntry = { id: string; 
/**
 * When the first segment began (RFC 3339), or when the session was made.
 */
started: string; 
/**
 * Recorded time, gaps excluded.
 */
duration_ms: number; 
/**
 * The lifecycle state's name: capturing, interrupted, queued,
 * processing, blocked, processing_failed, awaiting_destination, saved.
 */
state: string; 
/**
 * The stage started last: the running one, or the one a failed
 * session stopped at.
 */
stage: string | null; 
/**
 * The proposed or typed title, if the session has one (R28).
 */
title: string | null; 
/**
 * The number of speakers that processing found (KTD11). `None` before
 * the join, or when the transcript has no speaker marks.
 */
found_speakers: number | null; 
/**
 * The note's storage folder is unavailable, or its `session.md` cannot
 * be read now (R16). Opening it and its actions wait.
 */
storage_unavailable: boolean; 
/**
 * Work on the note on another computer, as the latest library scan
 * found it (KTD5). `None` when no other computer works on the note,
 * and always for a note that is not Saved on this computer.
 */
remote: RemoteView | null; 
/**
 * The note type that the app shows (KTD3): a type change that waits
 * for its move, else the type folder that holds the home folder.
 * `None` is General.
 */
note_type: string | null; 
/**
 * The tags of the note, as their exact texts (R9, R11).
 */
tags: string[]; 
/**
 * A file of the note folder gives no note (R6). The actions that
 * write to the note wait. `None` for a note whose files are valid.
 */
problem: NoteProblemView | null; 
/**
 * What the note waits for before its next stage can run, from the
 * runner (KTD10). `None` when it waits for nothing: its stage runs,
 * or it has no work.
 */
waits_for: WaitView | null }
/**
 * The settings that the app uses: the local settings of this computer and
 * the shared settings of the storage folder (KTD7). The local store holds
 * only the local fields. Each shared field comes from the shared view; a
 * value that this version does not know reads as the default here, and
 * `shared.unknown_values` names it.
 */
export type Settings = { settings_schema_version: number; interface_zoom_percent: number; 
/**
 * The chord that starts and stops a recording. `None` when the user
 * cleared it (R3). A stored string reads as `Some`, so no migration is
 * needed (KTD3).
 */
shortcut: string | null; 
/**
 * The chord that shows or hides the main window. Off by default (R5).
 */
show_window_shortcut: string | null; 
/**
 * The chord that pauses the recording note and continues the paused
 * note. Off by default (R16).
 */
pause_shortcut: string | null; 
/**
 * The chord that shows or hides the recording widget for the open
 * note. Off by default (R13).
 */
widget_shortcut: string | null; 
/**
 * The one storage folder (R1). The library lists the notes in it, and
 * the next note saves to it. Empty only until the launch sets the
 * default folder (R2, KTD12).
 */
storage_folder: string; 
/**
 * The AI provider that summaries use (R7). `None` sends no summary
 * request, and a new install has none (R11).
 */
active_provider: Provider | null; 
/**
 * The remembered address, model and context limit of each provider on
 * this computer (R10, R13, R15).
 */
providers: ProviderEntries; 
/**
 * This field and the five after it are the recognition configuration
 * in use on this computer (R18, KTD14). Recording, processing and
 * Transcribe Again read them. They change to `chosen_recognition` as
 * one unit when every model that it needs is on disk.
 */
default_speaker_count: SpeakerCountSetting | null; 
/**
 * Catalog id of the recognition model (KTD6).
 */
asr_model: string; 
/**
 * A streaming model transcribes during recording (R18, KD9).
 */
live_transcript: boolean; speaker_source: SpeakerSource; speaker_processing_mode: ProcessingMode; recognition_language: string | null; 
/**
 * A shared setting. The chosen recognition configuration (R18).
 */
chosen_recognition: RecognitionChoice; 
/**
 * The chosen configuration compared with the configuration in use,
 * and the downloads that it waits for (R19).
 */
recognition: RecognitionState; 
/**
 * The microphone a new note records from. `None` is "System default"
 * (R1, KTD17).
 */
microphone: MicrophoneChoice | null; 
/**
 * Whether a new note starts with system audio on (R6, KD13).
 */
system_audio_default: boolean; 
/**
 * A shared setting. What New Note and the recording shortcut do (R8,
 * R10): start a note that records, or open a note that does not
 * record. On by default.
 */
new_note_records: boolean; 
/**
 * Whether a recording that stops and cannot restart plays the alert
 * sound (R9, KTD1). On by default. Test Sound plays when it is off.
 */
alert_sound: boolean; 
/**
 * macOS only: the app has no Dock icon while no window is visible
 * (R2, R3). Off by default: the Dock icon stays, as is usual on macOS.
 */
hide_from_dock: boolean; 
/**
 * A shared setting. Whether a new note shows the recording widget: the
 * pill that is on screen while a note is open (R11). On by default. A
 * change applies to the next note (R14).
 */
show_recording_widget: boolean; 
/**
 * A shared setting. A release build checks for a newer release at
 * launch, each hour and at each wake (R9, R10). On by default. "Check
 * for Updates…" works when it is off (R11).
 */
check_updates_automatically: boolean; 
/**
 * A shared setting. When the audio of a saved note goes (R1, R2). On
 * by default, with a delay of 30 days. A value that this version does
 * not know shows as the default here and in `shared.unknown_values`.
 * The removal pass does not read this field: it reads
 * `SharedSnapshot::audio_removal_days`, which gives no delay for such a
 * value or while the shared settings are read-only.
 */
audio_removal: AudioRemovalSetting; 
/**
 * A shared setting. The custom summary prompts, in the order that
 * Settings shows them (KTD6).
 */
summary_prompts: SummaryPrompt[]; 
/**
 * A shared setting. The id of the prompt that the next summary uses.
 * An id that matches no prompt resolves to the Topic summary.
 */
active_summary_prompt: string; 
/**
 * Whether this computer can change the shared settings now, and the
 * values that this version does not know (R16, R17).
 */
shared: SharedState; 
/**
 * A shared setting. The Background text that each summary uses (R1,
 * R7). It is the cached text while the Background file or the storage
 * folder is not available (KTD3).
 */
background: string; 
/**
 * The most characters the Background can have (R6).
 */
background_limit: number; 
/**
 * Why the Background cannot change now, as UI text. `None` when
 * this computer can change it (R5, KTD3).
 */
background_read_only: string | null }
/**
 * The settings changed without a command from the surface, for example
 * when a picked model becomes the selected model after its download.
 */
export type SettingsChanged = { settings: Settings }
/**
 * A pane of the Settings window. The values agree with `PaneId` in
 * src/settings/Status.tsx.
 */
export type SettingsPane = "status" | "recording" | "destination" | "types" | "provider" | "summarization" | "recognition" | "about"
/**
 * An open Settings window must show this pane (KTD10). A new Settings
 * window reads its pane from its URL instead.
 */
export type SettingsPaneRequested = { pane: SettingsPane }
/**
 * Whether this computer can change the shared settings now (R16).
 */
export type SharedAvailability = { kind: "available" } | 
/**
 * The shared settings come from the local cache, or from the defaults
 * when there is no cache.
 */
{ kind: "read_only"; cause: ReadOnlyCause }
/**
 * The state of the shared settings, for the Settings window.
 */
export type SharedState = { availability: SharedAvailability; 
/**
 * The settings file comes from a newer version of Longhand, so it can
 * hold settings that this version does not show.
 */
newer_version: boolean; unknown_values: UnknownSharedValue[]; 
/**
 * The prompt files and the Background file can change now. This is
 * also true while only the settings file does not parse (R22).
 */
files_writable: boolean; 
/**
 * The settings file did not parse for about one minute (R22).
 */
damaged_file: DamagedFile | null }
/**
 * A press of the recording shortcut failed after it passed the arming
 * checks. The main window shows `text` on the page that it shows, as the
 * Record and Stop buttons show their errors.
 */
export type ShortcutFailed = { text: string }
/**
 * Which of the four shortcuts a command acts on.
 */
export type ShortcutKind = "recording" | "show_window" | "pause" | "widget"
/**
 * One shortcut's state (KTD7): off when `chord` is `None`, registered, or
 * failed with a reason in `error`.
 */
export type ShortcutStatus = { chord: string | null; registered: boolean; error: string | null }
export type ShortcutStatuses = { recording: ShortcutStatus; show_window: ShortcutStatus; pause: ShortcutStatus; widget: ShortcutStatus }
/**
 * The main window must show the page of this session (R3).
 */
export type ShowSession = { session_id: string }
export type SpeakerCount = { kind: "exact"; count: number } | { kind: "range"; min: number; max: number }
/**
 * An optional bound on how many people are speaking (R36).
 */
export type SpeakerCountSetting = { kind: "exact"; count: number } | { kind: "range"; min: number; max: number }
/**
 * The speaker-detection weights as one item (R7).
 */
export type SpeakerModelsStatus = { 
/**
 * The catalog ids, for one download of all of them.
 */
ids: string[]; 
/**
 * The sum of the sizes.
 */
size_bytes: number; 
/**
 * Present only when every weight is present.
 */
state: ModelState }
/**
 * Ordered speaker choices for automatic mode selection. The resolver still
 * checks runtime support, language, timing, and speaker count.
 */
export type SpeakerPreferences = { after_stop: SpeakerSource[]; during_recording: SpeakerSource[] }
/**
 * The speaker stage's progress in one processing attempt. Only the stage's
 * completion means 100%.
 */
export type SpeakerProgressView = { 
/**
 * A view keeps the value of the current attempt only.
 */
attempt: string; 
/**
 * The measured share of the whole note, 0 to 99. `None` before the
 * first measurement.
 */
percent: number | null; 
/**
 * False while the stage does work that it cannot measure.
 */
measuring: boolean }
export type SpeakerSource = "off" | "pyannote" | "sortformer" | "nemotron"
/**
 * What a Stop did to the note (R19).
 */
export type StopOutcome = 
/**
 * The note kept audio and waits for processing.
 */
{ kind: "recorded"; session_id: string } | 
/**
 * No segment was kept: every segment was under a second. The note
 * stays as a note with no audio, because it existed before this
 * recording or its notes have text.
 */
{ kind: "notes_only"; session_id: string } | 
/**
 * No segment was kept, the note started with this recording, and its
 * notes have no text. The note is a note with no audio now; the check
 * of empty notes removes it when the user leaves it (U6).
 */
{ kind: "empty_note"; session_id: string } | 
/**
 * The Stop cancelled the microphone open of a new note. No note was
 * made, and no note stopped.
 */
{ kind: "cancelled" } | 
/**
 * Some audio could not be added to the note, so the note is
 * Interrupted with its audio, and a later Stop or launch tries again.
 * The failed-capture alert tells the user: the page shows nothing.
 */
{ kind: "interrupted"; session_id: string }
/**
 * A summary prompt that the user made (R1, KTD6). The built-in prompts are
 * never saved: their text lives in `summarize::prompts`.
 */
export type SummaryPrompt = { id: string; name: string; text: string; 
/**
 * Empty for a prompt that the old local store holds: that store has
 * no title texts (KTD6).
 */
title_text?: string }
/**
 * One row of the prompt list that the Settings window shows.
 */
export type SummaryPromptEntry = { id: string; name: string; text: string; title_text: string; 
/**
 * A built-in prompt cannot be renamed, edited or deleted (R2).
 */
built_in: boolean; 
/**
 * The prompt text or the title instructions are over their limit, for
 * example after an edit outside Longhand (R21). A run uses the whole
 * text. Rename and delete stay available.
 */
over_limit: boolean; 
/**
 * The file is over the size limit that Longhand reads, so the list has
 * no texts of the prompt (R21). The texts are empty.
 */
too_large: boolean }
/**
 * The built-in prompts first, then the custom prompts, and the id of the
 * prompt that the next summary uses.
 */
export type SummaryPromptList = { prompts: SummaryPromptEntry[]; active: string; 
/**
 * The most characters a prompt text can have.
 */
text_limit: number; 
/**
 * The most characters a title text can have.
 */
title_text_limit: number }
export type SummaryView = { 
/**
 * Markdown.
 */
body: string; 
/**
 * Summarization failed and this stands in for it.
 */
stub: boolean; host: string | null; model: string | null; 
/**
 * The name of the prompt that made the summary. A summary made before
 * prompts had names, and a stub, have none.
 */
prompt: string | null; 
/**
 * The id of the prompt that made the summary (KTD4). A summary made
 * before prompt ids were recorded, and a stub, have none.
 */
prompt_id: string | null }
/**
 * The system audio permission, as the page reads it (R9, R10, KTD12).
 */
export type SystemAudioPermission = "allowed" | "denied" | 
/**
 * macOS has not asked yet, or its prompt waits for an answer.
 */
"not_asked" | 
/**
 * The private check is missing on this macOS.
 */
"unknown"
/**
 * What a tag rename or delete did (R13, R31).
 */
export type TagEdit = { 
/**
 * The number of notes that had the tag.
 */
changed: number; 
/**
 * The tag list after the edit.
 */
tags: TagEntry[] }
/**
 * One tag of the tag list (R12, KTD10).
 */
export type TagEntry = { 
/**
 * The spelling on the note with the earliest start that has the tag
 * (R30).
 */
text: string; 
/**
 * The key of the tag: the text with no spaces at its ends or around
 * `::`, in lower case. Two tags with one key are the same tag.
 */
key: string; 
/**
 * The number of notes with the tag (R31).
 */
count: number }
/**
 * The transcription model of a Transcribe Again run, for the dialog.
 */
export type TranscribeAgainCheck = { model_id: string; model_name: string }
/**
 * Why Transcribe Again cannot start. `in_settings` is true when the user
 * can fix the cause in Settings (KTD4).
 */
export type TranscribeAgainRefusal = { message: string; in_settings: boolean }
/**
 * What a type change did (R5). The note has the new type in every case
 * but `Unchanged`.
 */
export type TypeChangeResult = 
/**
 * The note has this type already. A waiting change back to the type
 * of its folder is cleared.
 */
{ kind: "unchanged" } | 
/**
 * The home folder is in the folder of the new type, or is made there
 * when the note writes its folder.
 */
{ kind: "done" } | 
/**
 * A computer records or processes the note: its folder moves when the
 * note is free.
 */
{ kind: "later" } | 
/**
 * The folder could not move now. It moves later. The text says why.
 */
{ kind: "kept"; message: string }
/**
 * A value in the shared settings file that this version does not know.
 * Longhand keeps it in the file (R17).
 */
export type UnknownSharedValue = { key: string; 
/**
 * The value as JSON text.
 */
value: string }
/**
 * What the update window shows, and what the manager does in the
 * background. A state with a view shows the update window.
 */
export type UpdateState = 
/**
 * Nothing to show.
 */
{ state: "idle" } | 
/**
 * A check runs. `manual` is true for "Check for Updates…".
 */
{ state: "checking"; manual: boolean } | 
/**
 * A newer build is offered (R13).
 */
{ state: "offered"; version: string; current: string } | 
/**
 * A newer build is found while busy. The offer shows when busy ends (R14).
 */
{ state: "held"; version: string } | 
/**
 * The result of a manual check: no newer build.
 */
{ state: "up_to_date"; current: string } | 
/**
 * The result of a manual check that failed.
 */
{ state: "check_failed"; error: string } | 
/**
 * The result of a manual check in a build that is not a release build.
 */
{ state: "local_build" } | 
/**
 * The build downloads (R16). `total` is none when the server sends no size.
 */
{ state: "downloading"; version: string; downloaded: number; total: number | null } | 
/**
 * The download, the signature check or the install failed (R18).
 */
{ state: "failed"; version: string; error: string } | 
/**
 * A download error while busy. It shows when busy ends (R3 of the
 * notice timing plan).
 */
{ state: "failed_held"; version: string; error: string } | 
/**
 * The build is downloaded while busy. The ready question shows when busy
 * ends (R17). `confirmed` is true when the user chose the build ("Relaunch
 * Now" or a download), so a quit installs it also when a newer release
 * replaced it (KTD8).
 */
{ state: "ready_held"; version: string; confirmed: boolean } | 
/**
 * The build is downloaded: "Relaunch Now" or "Later" (R17).
 */
{ state: "ready"; version: string } | 
/**
 * After "Later": the build installs at the next quit.
 */
{ state: "waiting_for_quit"; version: string } | 
/**
 * The build installs, and the app restarts.
 */
{ state: "installing"; version: string }
/**
 * The update state changed. The update window follows it.
 */
export type UpdateStateChanged = { state: UpdateState; 
/**
 * The user asked for the window, so it has the focus and Return
 * chooses the default button (KTD6).
 */
with_key: boolean }
/**
 * What a note waits for before its next stage can run (KTD10).
 */
export type WaitView = 
/**
 * A recording is active, and the next stage is an audio stage.
 */
"recording" | 
/**
 * Another note has the local permit or is in its audio stages.
 */
"another_note" | 
/**
 * The note waits for its turn in the summary queue: a new note, or a
 * regeneration of a saved note.
 */
"summary_turn" | 
/**
 * A model that the note needs is not on disk.
 */
"model"
/**
 * A part of a note that the sync has not delivered yet (R6).
 */
export type WaitingPart = "transcript" | "summary" | "notes" | "audio"
export type WebviewLogLevel = "error" | "warn" | "info"
/**
 * The pointer entered, moved on or left the pill (KTD6). WebKit sends
 * hover events late to a panel that is never the key window, so a native
 * tracking area sends this on macOS, and the page sets the hover itself.
 */
export type WidgetPointer = { inside: boolean; 
/**
 * The pointer position in page pixels, from the top left.
 */
x: number; y: number }
/**
 * The pill window was shown. The page reads the status again, because a
 * hidden page can hold an old state (KTD10).
 */
export type WidgetShown = null
export type ZoomAction = "increase" | "decrease" | "reset"

/** tauri-specta globals **/

import {
	invoke as TAURI_INVOKE,
	Channel as TAURI_CHANNEL,
} from "@tauri-apps/api/core";
import * as TAURI_API_EVENT from "@tauri-apps/api/event";
import { type WebviewWindow as __WebviewWindow__ } from "@tauri-apps/api/webviewWindow";

type __EventObj__<T> = {
	listen: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.listen<T>>;
	once: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.once<T>>;
	emit: null extends T
		? (payload?: T) => ReturnType<typeof TAURI_API_EVENT.emit>
		: (payload: T) => ReturnType<typeof TAURI_API_EVENT.emit>;
};

export type Result<T, E> =
	| { status: "ok"; data: T }
	| { status: "error"; error: E };

function __makeEvents__<T extends Record<string, any>>(
	mappings: Record<keyof T, string>,
) {
	return new Proxy(
		{} as unknown as {
			[K in keyof T]: __EventObj__<T[K]> & {
				(handle: __WebviewWindow__): __EventObj__<T[K]>;
			};
		},
		{
			get: (_, event) => {
				const name = mappings[event as keyof T];

				return new Proxy((() => {}) as any, {
					apply: (_, __, [window]: [__WebviewWindow__]) => ({
						listen: (arg: any) => window.listen(name, arg),
						once: (arg: any) => window.once(name, arg),
						emit: (arg: any) => window.emit(name, arg),
					}),
					get: (_, command: keyof __EventObj__<any>) => {
						switch (command) {
							case "listen":
								return (arg: any) => TAURI_API_EVENT.listen(name, arg);
							case "once":
								return (arg: any) => TAURI_API_EVENT.once(name, arg);
							case "emit":
								return (arg: any) => TAURI_API_EVENT.emit(name, arg);
						}
					},
				});
			},
		},
	);
}
